import { test, expect } from '@playwright/test';

test.describe('Payment Flow - Apply Promo Code', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/checkout');
  });

  test('should apply promo code and show discounted total', async ({ page }) => {
    await page.getByLabel('Promo Code').fill('PROMO123');
    await page.getByRole('button', { name: 'Apply' }).click();

    const discountedTotal = await page.getByText('Total: $80.00'); // Assuming original total was $100.00
    await expect(discountedTotal).toBeVisible();
  });

  test('should show error message for invalid promo code', async ({ page }) => {
    await page.getByLabel('Promo Code').fill('INVALIDCODE');
    await page.getByRole('button', { name: 'Apply' }).click();

    const errorMessage = await page.getByText('Invalid promo code. Please try again.');
    await expect(errorMessage).toBeVisible();
  });
});
